package ru.mytv.launcher;
import android.app.*;
import android.content.*;
import android.content.pm.*;
import android.os.*;
import android.view.View;
import android.widget.*;
import java.io.*;
import java.net.*;
import java.nio.file.*;
import java.util.*;
import org.json.*;

public class ProgressUpdates extends Updates {
 AlertDialog dialog;TextView info,status;ProgressBar progress;volatile boolean cancelled;volatile HttpURLConnection connection;
 ProgressUpdates(MainActivity a){super(a);}
 void cancel(){cancelled=true;HttpURLConnection c=connection;if(c!=null)c.disconnect();}
 @Override void close(){cancel();if(dialog!=null)dialog.dismiss();super.close();}
 @Override void check(boolean manual){
  if(!manual)return;if(!activity.live())return;if(busy){if(dialog!=null&&!dialog.isShowing())dialog.show();return;}if(activity.getPackageName().endsWith(".test")){activity.message("Самообновление доступно в релизной сборке.");return;}
  PackageInfo own;try{own=activity.getPackageManager().getPackageInfo(activity.getPackageName(),PackageManager.GET_SIGNATURES);}catch(Exception e){activity.message(e.toString());return;}cancelled=false;busy=true;LinearLayout box=new LinearLayout(activity);box.setOrientation(1);box.setPadding(activity.dp(24),activity.dp(16),activity.dp(24),activity.dp(16));long checked=activity.getSharedPreferences("updateStatus",0).getLong("checked",0);String date=checked==0?"ещё не выполнялась":android.text.format.DateFormat.format("dd.MM HH:mm",new Date(checked)).toString();
  info=activity.text("Установлена: "+own.versionName+"\nПоследняя ручная проверка: "+date,14);box.addView(info);status=activity.text("Проверяю обновления на GitHub…",16);status.setPadding(0,activity.dp(16),0,activity.dp(12));box.addView(status);progress=new ProgressBar(activity,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(1000);progress.setIndeterminate(true);box.addView(progress,new LinearLayout.LayoutParams(-1,activity.dp(16)));dialog=new AlertDialog.Builder(activity).setTitle("Обновление приложения").setView(box).setPositiveButton("Установить",null).setNegativeButton("Закрыть",(d,n)->cancel()).create();dialog.setCanceledOnTouchOutside(false);dialog.setOnCancelListener(d->cancel());dialog.setOnDismissListener(d->{if(busy)cancel();});dialog.show();dialog.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(false);pool.submit(()->runUpdate(own));
 }
 void display(String text,long done,long total){ui.post(()->{if(cancelled||activity.isDestroyed())return;status.setText(text);progress.setVisibility(View.VISIBLE);progress.setIndeterminate(total<=0);if(total>0)progress.setProgress((int)Math.min(1000,done*1000/total));});}
 void finishState(String text,File apk){ui.post(()->{busy=false;if(cancelled||activity.isDestroyed())return;status.setText(text);progress.setVisibility(View.GONE);Button b=dialog.getButton(AlertDialog.BUTTON_POSITIVE);b.setEnabled(true);b.setText(apk==null?"Повторить":"Установить");b.setOnClickListener(v->{dialog.dismiss();if(apk==null)check(true);else install(apk);});});}
 void runUpdate(PackageInfo own){File part=new File(activity.getCacheDir(),"update.part");try{JSONObject r=new JSONObject(new String(Updates.fetch("https://api.github.com/repos/"+REPO+"/releases/latest",1048576),java.nio.charset.StandardCharsets.UTF_8));if(cancelled)throw new IOException("Отменено");String tag=r.getString("tag_name");String clean=tag.startsWith("v")?tag.substring(1):tag;String[] p=clean.split("[.]");if(p.length!=3)throw new IOException("Неподдерживаемый номер версии");int major=Integer.parseInt(p[0]),minor=Integer.parseInt(p[1]),patch=Integer.parseInt(p[2]);if(major<0||minor<0||minor>99||patch<0||patch>99)throw new IOException("Неверный номер версии");long expected=(long)major*10000+minor*100+patch;long checked=System.currentTimeMillis();activity.getSharedPreferences("updateStatus",0).edit().putLong("checked",checked).apply();ui.post(()->{if(!cancelled&&!activity.isDestroyed())info.setText("Установлена: "+own.versionName+"\nНа GitHub: "+tag+"\nПроверено: "+android.text.format.DateFormat.format("dd.MM HH:mm",new Date(checked)));});if(expected<=version(own)){finishState("Установлена актуальная версия.",null);return;}JSONArray assets=r.getJSONArray("assets");String url=null;for(int i=0;i<assets.length();i++)if("My-TV.apk".equals(assets.getJSONObject(i).getString("name")))url=assets.getJSONObject(i).getString("browser_download_url");if(url==null||!url.startsWith("https://github.com/"+REPO+"/releases/download/"))throw new IOException("APK релиза не найден");display("Подключаюсь для скачивания…",0,-1);download(url,part);if(cancelled)throw new IOException("Отменено");display("Проверяю пакет и цифровую подпись…",0,-1);verify(part,own,expected);if(cancelled)throw new IOException("Отменено");File ready=new File(activity.getCacheDir(),"update.apk");Files.move(part.toPath(),ready.toPath(),StandardCopyOption.REPLACE_EXISTING);finishState("Готово к установке. Подпись проверена.",ready);}catch(Exception e){part.delete();finishState("Ошибка обновления: "+(e.getMessage()==null?e.getClass().getSimpleName():e.getMessage()),null);}}
 void download(String value,File target)throws Exception{URL url=new URL(value);HttpURLConnection c=null;try{for(int redirects=0;;redirects++){if(cancelled)throw new IOException("Отменено");if(!"https".equals(url.getProtocol()))throw new IOException("Допускается только HTTPS");c=(HttpURLConnection)url.openConnection();connection=c;c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(20000);c.setRequestProperty("User-Agent","MyTVLauncher/0.3.2");int code=c.getResponseCode();if(code>=300&&code<400){String location=c.getHeaderField("Location");c.disconnect();if(location==null||redirects>=5)throw new IOException("Ошибка перенаправления");url=new URL(url,location);continue;}if(code!=200)throw new IOException("HTTP "+code);break;}long total=c.getContentLengthLong();if(total>33554432)throw new IOException("APK слишком большой");long done=0,last=0;display("Скачиваю APK…",0,total);try(InputStream in=c.getInputStream();FileOutputStream out=new FileOutputStream(target)){byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1){if(cancelled)throw new IOException("Отменено");done+=n;if(done>33554432)throw new IOException("APK слишком большой");out.write(b,0,n);long now=SystemClock.elapsedRealtime();if(now-last>=100){last=now;String text=total>0?String.format(Locale.getDefault(),"Скачиваю: %d%% · %.1f / %.1f КБ",done*100/total,done/1024.0,total/1024.0):String.format(Locale.getDefault(),"Скачано %.1f КБ",done/1024.0);display(text,done,total);}}}if(total>0&&done!=total)throw new IOException("Файл скачан не полностью");}finally{if(c!=null)c.disconnect();connection=null;}}
}
